settings.custom_liquid:
{%- liquid
  assign p = closest.product
  assign tone = '#074f3b'
  assign num = ''
  assign tags = p.type
  assign demo = ''
  assign pw = ''
  case p.handle
    when 'digital-product'
      assign num = '01'
      assign tags = 'Fashion · Lifestyle · Editorial'
      assign demo = 'https://black-and-white-8fiua40n.myshopify.com/'
      assign pw = 'Demo-BW'
    when 'terra-oddity'
      assign tone = '#b4472b'
      assign num = '02'
      assign tags = 'Ceramics · Homeware · Makers'
      assign demo = 'https://terraoddity-f0y9ivfe.myshopify.com/'
      assign pw = 'teathu'
  endcase
  assign demo = p.metafields.custom.demo_url | default: demo
  assign name = p.title | split: ' - ' | first
  assign save = 0
  if p.compare_at_price > p.price
    assign save = p.compare_at_price | minus: p.price | times: 100 | divided_by: p.compare_at_price
  endif
-%}
<style>
  .card-gallery[data-product-id="{{ p.id }}"]{border-color:{{ tone }}!important;transition:transform .35s cubic-bezier(.2,.7,.2,1),box-shadow .35s cubic-bezier(.2,.7,.2,1)}
  .product-grid__item:hover .card-gallery[data-product-id="{{ p.id }}"],.product-grid__item:focus-within .card-gallery[data-product-id="{{ p.id }}"]{transform:translate(-4px,-4px);box-shadow:8px 8px 0 {{ tone }}}
  @media (prefers-reduced-motion:reduce){.card-gallery[data-product-id="{{ p.id }}"]{transition:none}}
  .tci{--tc:#074f3b;position:relative;z-index:10;display:flex;flex-direction:column;gap:10px;width:100%;padding-top:6px;color:inherit}
  .tci__top{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:11px;letter-spacing:.12em;text-transform:uppercase}
  .tci__no{display:inline-flex;align-items:center;gap:8px;color:var(--tc);font-weight:600}
  .tci__no::before{content:'';width:18px;height:2px;background:currentColor}
  .tci__tags{opacity:.6}
  .tci__title{margin:0;font-family:var(--font-heading--family);font-size:clamp(1.5rem,2.4vw,2.1rem);line-height:1.05;letter-spacing:-.01em}
  .tci__title a{color:inherit;text-decoration:none;background:linear-gradient(currentColor,currentColor) 0 100%/0 1px no-repeat;transition:background-size .3s}
  .tci__title a:hover,.tci__title a:focus-visible{background-size:100% 1px}
  .tci__price{display:flex;align-items:baseline;flex-wrap:wrap;gap:6px 10px;font-size:1.0625rem}
  .tci__price b{font-weight:700}
  .tci__price s{opacity:.55;font-size:.9375rem}
  .tci__save{padding:3px 8px;background:var(--tc);color:#fff;font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase}
  .tci__meta{margin:0;font-size:13px;opacity:.7}
  .tci__actions{display:flex;flex-wrap:wrap;gap:6px;margin-top:4px}
  .tci__actions a,.tci__actions button{display:inline-flex;align-items:center;gap:6px;min-height:38px;padding:0 12px;font:inherit;font-size:12px;letter-spacing:.06em;text-transform:uppercase;text-decoration:none;cursor:pointer;transition:background .2s,color .2s}
  .tci__demo{background:var(--tc);color:#fff;border:1px solid var(--tc)}
  .tci__demo:hover{background:transparent;color:var(--tc)}
  .tci__pass{background:transparent;color:var(--tc);border:1px dashed var(--tc)}
  .tci__pass code{font-weight:600;text-transform:none;letter-spacing:.02em}
  .tci__more{margin-left:auto;color:inherit;border:0;background:none;padding-inline:4px!important}
  .tci__more:hover{color:var(--tc)}
  .tci a:focus-visible,.tci button:focus-visible{outline:2px solid var(--tc);outline-offset:2px}
  @media screen and (max-width:749px){.tci__more{margin-left:0}}
</style>
<script>if(!window.bwCopy){window.bwCopy=function(t){var legacy=function(){var a=document.createElement('textarea');a.value=t;a.setAttribute('readonly','');a.style.cssText='position:fixed;top:0;left:0;opacity:0;pointer-events:none';document.body.appendChild(a);a.focus();a.select();a.setSelectionRange(0,t.length);var ok=false;try{ok=document.execCommand('copy')}catch(e){}a.remove();return ok};if(navigator.clipboard&&window.isSecureContext){return navigator.clipboard.writeText(t).then(function(){return true},function(){return legacy()})}return Promise.resolve(legacy())};document.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-bw-copy]');if(!b)return;if(b.tagName!=='A')e.preventDefault();e.stopPropagation();window.bwCopy(b.getAttribute('data-bw-copy')).then(function(ok){var s=b.querySelector('[data-bw-state]');if(!s)return;var o=s.getAttribute('data-bw-label')||s.textContent;s.setAttribute('data-bw-label',o);s.textContent=ok?'Copied':'Press Ctrl+C';setTimeout(function(){s.textContent=o},1800)})},true)}</script>
<div class="tci" style="--tc: {{ tone }}">
  <div class="tci__top">
    {%- if num != blank -%}<span class="tci__no">Theme {{ num }}</span>{%- endif -%}
    {%- if tags != blank -%}<span class="tci__tags">{{ tags }}</span>{%- endif -%}
  </div>
  <h3 class="tci__title"><a href="{{ p.url }}">{{ name | escape }}</a></h3>
  <div class="tci__price">
    <b>{{ p.price | money }}</b>
    {%- if p.compare_at_price > p.price -%}
      <s>{{ p.compare_at_price | money }}</s>
      <span class="tci__save">Save {{ save }}%</span>
    {%- endif -%}
  </div>
  <p class="tci__meta">One-time payment · Lifetime access · Online Store 2.0</p>
  <div class="tci__actions">
    {%- if demo != blank -%}
      <a class="tci__demo" href="{{ demo }}" target="_blank" rel="noopener"{% if pw != blank %} data-bw-copy="{{ pw }}"{% endif %}>View demo &#8599;</a>
      {%- if pw != blank -%}
        <button class="tci__pass" type="button" aria-label="Copy demo password {{ pw }}" data-bw-copy="{{ pw }}">Password <code>{{ pw }}</code> &#183; <span data-bw-state>Copy</span></button>
      {%- endif -%}
    {%- endif -%}
    <a class="tci__more" href="{{ p.url }}">Details &#8594;</a>
  </div>
</div>
